class Solution {
    public String findOrder(String [] dict, int N, int K) {
        List<Integer>[] adj = new ArrayList[K];
        for(int i=0; i<K; i++){
            adj[i] = new ArrayList<>();
        }
        for(int i=0; i<N-1; i++){
            char[] s1 = dict[i].toCharArray();
            char[] s2 = dict[i+1].toCharArray();
            int len = Math.min(s1.length, s2.length);
            for(int c=0; c<len; c++){
                if(s1[c] != s2[c]){
                    adj[s1[c] - 'a'].add(s2[c]-'a');
                    break;
                }
            }
        }
        List<Integer> topos = topologicalSort(K, adj);
        StringBuilder res= new StringBuilder();
        for(int topo : topos){
            char c = (char)(topo + 'a');
            res.append(c);
        }
        return res.toString();
    }
    List<Integer> topologicalSort(int k, List<Integer>[] adj){
        int[] indegree = new int[k];
        for(int i=0; i<k; i++){
            for(int n : adj[i]){
                indegree[n]++;
            }
        }
        LinkedList<Integer> queue = new LinkedList<>();
        for(int i=0; i<k; i++){
            if(indegree[i] == 0) queue.add(i);
        }
        List<Integer> res = new ArrayList<>();
        while(!queue.isEmpty()){
            int curr = queue.pop();
            res.add(curr);
            for(int ad : adj[curr]){
                indegree[ad]--;
                if(indegree[ad] == 0){
                    queue.add(ad);
                }
            }
        }
        return res;
    }
}
